using System.Collections.Concurrent;

public interface IProductEnricher
{
    Task<IReadOnlyList<ProductCard>> EnrichAsync(IReadOnlyList<int> ids, CancellationToken ct);
}

public sealed class ProductEnricher(IProductClient client, int maxParallel) : IProductEnricher
{
    private readonly SemaphoreSlim _gate = new(maxParallel, maxParallel);
    private readonly ConcurrentDictionary<int, ProductCard> _cache = new();

    public async Task<IReadOnlyList<ProductCard>> EnrichAsync(IReadOnlyList<int> ids, CancellationToken ct)
    {
        var results = new ProductCard[ids.Count];
        var tasks = ids.Select((id, index) => LoadOneAsync(id, index, results, ct)).ToArray();
        await Task.WhenAll(tasks).ConfigureAwait(false);
        return results;
    }

    private async Task LoadOneAsync(int id, int index, ProductCard[] results, CancellationToken ct)
    {
        if (_cache.TryGetValue(id, out var hit))
        {
            results[index] = hit;
            return;
        }
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            if (_cache.TryGetValue(id, out hit))
            {
                results[index] = hit;
                return;
            }
            var card = await client.GetAsync(id, ct).ConfigureAwait(false);
            results[index] = _cache.GetOrAdd(id, card);
        }
        finally { _gate.Release(); }
    }
}

public interface IProductClient { Task<ProductCard> GetAsync(int id, CancellationToken ct); }
public sealed record ProductCard(int Id, string Title, decimal Price);
