public interface IAsyncBatcher<TItem, TResult>
{
    ValueTask<TResult> EnqueueAsync(TItem item, CancellationToken ct);
}

public sealed class AsyncBatcher<TItem, TResult> : IAsyncBatcher<TItem, TResult>, IAsyncDisposable
{
    private readonly Func<IReadOnlyList<TItem>, CancellationToken, Task<IReadOnlyList<TResult>>> _processor;
    private readonly int _maxBatchSize;
    private readonly TimeSpan _maxDelay;
    private readonly TimeProvider _time;
    private readonly Channel<(TItem Item, TaskCompletionSource<TResult> Tcs)> _channel =
        Channel.CreateUnbounded<(TItem, TaskCompletionSource<TResult>)>();
    private readonly CancellationTokenSource _cts = new();
    private readonly Task _loop;

    public AsyncBatcher(
        Func<IReadOnlyList<TItem>, CancellationToken, Task<IReadOnlyList<TResult>>> processor,
        int maxBatchSize,
        TimeSpan maxDelay,
        TimeProvider? time = null)
    {
        if (maxBatchSize <= 0) throw new ArgumentOutOfRangeException(nameof(maxBatchSize));
        _processor = processor;
        _maxBatchSize = maxBatchSize;
        _maxDelay = maxDelay;
        _time = time ?? TimeProvider.System;
        _loop = Task.Run(() => RunAsync(_cts.Token));
    }

    public async ValueTask<TResult> EnqueueAsync(TItem item, CancellationToken ct)
    {
        var tcs = new TaskCompletionSource<TResult>(TaskCreationOptions.RunContinuationsAsynchronously);
        await _channel.Writer.WriteAsync((item, tcs), ct).ConfigureAwait(false);
        return await tcs.Task.WaitAsync(ct).ConfigureAwait(false);
    }

    private async Task RunAsync(CancellationToken ct)
    {
        var batch = new List<(TItem Item, TaskCompletionSource<TResult> Tcs)>(_maxBatchSize);
        try
        {
            // Ждём первый элемент без таймаута: пустой батч не отправляем.
            while (await _channel.Reader.WaitToReadAsync(ct).ConfigureAwait(false))
            {
                batch.Clear();
                var deadline = _time.GetUtcNow() + _maxDelay;
                while (batch.Count < _maxBatchSize)
                {
                    if (_channel.Reader.TryRead(out var next))
                    {
                        batch.Add(next);
                        continue;
                    }
                    var remaining = deadline - _time.GetUtcNow();
                    if (remaining <= TimeSpan.Zero) break;
                    using var delayCts = new CancellationTokenSource(remaining, _time);
                    using var linked = CancellationTokenSource.CreateLinkedTokenSource(ct, delayCts.Token);
                    try
                    {
                        if (!await _channel.Reader.WaitToReadAsync(linked.Token).ConfigureAwait(false)) break;
                    }
                    catch (OperationCanceledException) when (!ct.IsCancellationRequested)
                    {
                        break;
                    }
                }
                if (batch.Count > 0) await FlushAsync(batch, ct).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
        }
        finally
        {
            foreach (var (_, tcs) in batch) tcs.TrySetCanceled();
            while (_channel.Reader.TryRead(out var left)) left.Tcs.TrySetCanceled();
        }
    }

    private async Task FlushAsync(List<(TItem Item, TaskCompletionSource<TResult> Tcs)> batch, CancellationToken ct)
    {
        try
        {
            var results = await _processor(batch.Select(x => x.Item).ToList(), ct).ConfigureAwait(false);
            if (results.Count != batch.Count)
                throw new InvalidOperationException("Processor must return one result per item");
            for (var i = 0; i < batch.Count; i++) batch[i].Tcs.TrySetResult(results[i]);
        }
        catch (Exception ex)
        {
            foreach (var (_, tcs) in batch) tcs.TrySetException(ex);
        }
        batch.Clear();
    }

    public async ValueTask DisposeAsync()
    {
        _channel.Writer.TryComplete();
        _cts.Cancel();
        await _loop.ConfigureAwait(false);
        _cts.Dispose();
    }
}
