public interface IRetryPolicy
{
    Task<T> ExecuteAsync<T>(
        Func<CancellationToken, Task<T>> action,
        CancellationToken ct);
}

public sealed class RetryPolicy : IRetryPolicy
{
    private readonly int _maxAttempts;
    private readonly TimeSpan _baseDelay;
    private readonly Random _jitter = new();

    public RetryPolicy(int maxAttempts = 5, TimeSpan? baseDelay = null)
    {
        _maxAttempts = maxAttempts;
        _baseDelay = baseDelay ?? TimeSpan.FromMilliseconds(100);
    }

    public async Task<T> ExecuteAsync<T>(
        Func<CancellationToken, Task<T>> action,
        CancellationToken ct)
    {
        Exception? last = null;
        for (var attempt = 0; attempt < _maxAttempts; attempt++)
        {
            ct.ThrowIfCancellationRequested();
            try
            {
                return await action(ct).ConfigureAwait(false);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception ex) when (attempt < _maxAttempts - 1)
            {
                last = ex;
                var exp = Math.Pow(2, attempt);
                var jitterMs = _jitter.Next(0, (int)(_baseDelay.TotalMilliseconds * 0.25) + 1);
                var delay = TimeSpan.FromMilliseconds(_baseDelay.TotalMilliseconds * exp + jitterMs);
                await Task.Delay(delay, ct).ConfigureAwait(false);
            }
        }
        throw last ?? new InvalidOperationException("Retry exhausted");
    }
}
