public interface ITtlCache<TKey, TValue> where TKey : notnull
{
    TValue GetOrAdd(TKey key, Func<TKey, TValue> factory);
    bool TryGet(TKey key, out TValue value);
}

public sealed class TtlCache<TKey, TValue> : ITtlCache<TKey, TValue> where TKey : notnull
{
    private readonly object _sync = new();
    private readonly TimeSpan _ttl;
    private readonly TimeProvider _time;
    private readonly Dictionary<TKey, Entry> _map = new();

    private sealed record Entry(TValue Value, DateTimeOffset ExpiresAt);

    public TtlCache(TimeSpan ttl, TimeProvider? time = null)
    {
        _ttl = ttl;
        _time = time ?? TimeProvider.System;
    }

    public TValue GetOrAdd(TKey key, Func<TKey, TValue> factory)
    {
        lock (_sync)
        {
            if (_map.TryGetValue(key, out var e) && e.ExpiresAt > _time.GetUtcNow())
                return e.Value;
            var value = factory(key);
            _map[key] = new Entry(value, _time.GetUtcNow().Add(_ttl));
            return value;
        }
    }

    public bool TryGet(TKey key, out TValue value)
    {
        lock (_sync)
        {
            if (_map.TryGetValue(key, out var e) && e.ExpiresAt > _time.GetUtcNow())
            {
                value = e.Value;
                return true;
            }
            value = default!;
            return false;
        }
    }
}
