public interface ILruCache<TKey, TValue> where TKey : notnull
{
    bool TryGet(TKey key, out TValue value);
    void Set(TKey key, TValue value);
}

public sealed class LruCache<TKey, TValue> : ILruCache<TKey, TValue> where TKey : notnull
{
    private readonly object _sync = new();
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _map = new();
    private readonly LinkedList<(TKey Key, TValue Value)> _list = new();

    public LruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
    }

    public bool TryGet(TKey key, out TValue value)
    {
        lock (_sync)
        {
        if (!_map.TryGetValue(key, out var node))
        {
            value = default!;
            return false;
        }
        _list.Remove(node);
        _list.AddFirst(node);
        value = node.Value.Value;
        return true;
        }
    }

    public void Set(TKey key, TValue value)
    {
        lock (_sync)
        {
        if (_map.TryGetValue(key, out var existing))
        {
            existing.Value = (key, value);
            _list.Remove(existing);
            _list.AddFirst(existing);
            return;
        }
        var node = _list.AddFirst((key, value));
        _map[key] = node;
        if (_map.Count > _capacity)
        {
            var tail = _list.Last!;
            _map.Remove(tail.Value.Key);
            _list.RemoveLast();
        }
        }
    }
}
