public interface IKeyedConcurrencyLimiter
{
    Task<T> RunAsync<T>(string key, Func<CancellationToken, Task<T>> action, CancellationToken ct);
}

public sealed class KeyedConcurrencyLimiter : IKeyedConcurrencyLimiter, IDisposable
{
    private readonly object _sync = new();
    private readonly int _perKeyLimit;
    private readonly Dictionary<string, Gate> _gates = new();

    private sealed class Gate : IDisposable
    {
        public readonly SemaphoreSlim Semaphore;
        public int RefCount;
        public Gate(int limit) => Semaphore = new SemaphoreSlim(limit, limit);
        public void Dispose() => Semaphore.Dispose();
    }

    public KeyedConcurrencyLimiter(int perKeyLimit = 1) => _perKeyLimit = perKeyLimit;

    public async Task<T> RunAsync<T>(string key, Func<CancellationToken, Task<T>> action, CancellationToken ct)
    {
        Gate gate;
        lock (_sync)
        {
            if (!_gates.TryGetValue(key, out gate!))
            {
                gate = new Gate(_perKeyLimit);
                _gates[key] = gate;
            }
            gate.RefCount++;
        }
        try
        {
            await gate.Semaphore.WaitAsync(ct).ConfigureAwait(false);
        }
        catch
        {
            ReleaseGate(key, gate);
            throw;
        }
        try
        {
            return await action(ct).ConfigureAwait(false);
        }
        finally
        {
            gate.Semaphore.Release();
            ReleaseGate(key, gate);
        }
    }

    private void ReleaseGate(string key, Gate gate)
    {
        lock (_sync)
        {
            gate.RefCount--;
            if (gate.RefCount == 0)
            {
                _gates.Remove(key);
                gate.Dispose();
            }
        }
    }

    public void Dispose()
    {
        lock (_sync)
        {
            foreach (var g in _gates.Values) g.Dispose();
            _gates.Clear();
        }
    }
}
