public sealed class SlidingWindowCounter : ISlidingWindowCounter
{
    private readonly object _sync = new();
    private readonly TimeSpan _window;
    private readonly TimeProvider _time;
    private readonly Queue<DateTimeOffset> _events = new();

    public SlidingWindowCounter(TimeSpan window, TimeProvider? time = null)
    {
        _window = window;
        _time = time ?? TimeProvider.System;
    }

    public void RecordEvent()
    {
        lock (_sync)
        {
            Prune();
            _events.Enqueue(_time.GetUtcNow());
        }
    }

    public int CountInWindow()
    {
        lock (_sync)
        {
            Prune();
            return _events.Count;
        }
    }

    private void Prune()
    {
        var cutoff = _time.GetUtcNow() - _window;
        while (_events.Count > 0 && _events.Peek() < cutoff)
            _events.Dequeue();
    }
}
