public sealed class TimeoutBudget : ITimeoutBudget, IDisposable
{
    private readonly CancellationTokenSource _cts;
    private readonly TimeProvider _time;
    private readonly DateTimeOffset _deadline;

    public TimeoutBudget(TimeSpan total, TimeProvider? time = null, CancellationToken outer = default)
    {
        _time = time ?? TimeProvider.System;
        _deadline = _time.GetUtcNow().Add(total);
        _cts = CancellationTokenSource.CreateLinkedTokenSource(outer);
        _cts.CancelAfter(total);
    }

    public CancellationToken Token => _cts.Token;

    public TimeSpan Remaining
    {
        get
        {
            var r = _deadline - _time.GetUtcNow();
            return r > TimeSpan.Zero ? r : TimeSpan.Zero;
        }
    }

    public ITimeoutBudget CreateChild(TimeSpan maxSlice)
    {
        var slice = Remaining < maxSlice ? Remaining : maxSlice;
        return new TimeoutBudget(slice, _time, _cts.Token);
    }

    public void Dispose() => _cts.Dispose();
}
