}

public sealed class AdapterCorrelator : IAdapterCorrelator
{
    private readonly object _sync = new();
    private readonly Dictionary<string, TaskCompletionSource<object>> _pending = new();

    public async Task<TResponse> SendAsync<TRequest, TResponse>(
        TRequest request,
        Func<TRequest, string> getCorrelationId,
        Func<TRequest, CancellationToken, Task> send,
        CancellationToken ct)
    {
        var id = getCorrelationId(request);
        var tcs = new TaskCompletionSource<object>(TaskCreationOptions.RunContinuationsAsynchronously);
        lock (_sync)
        {
            if (!_pending.TryAdd(id, tcs))
                throw new InvalidOperationException($"Duplicate correlation id '{id}'");
        }
        try
        {
            using var reg = ct.Register(() => tcs.TrySetCanceled(ct));
            await send(request, ct).ConfigureAwait(false);
            var result = await tcs.Task.ConfigureAwait(false);
            return (TResponse)result;
        }
        finally
        {
            lock (_sync)
            {
                if (_pending.TryGetValue(id, out var current) && ReferenceEquals(current, tcs))
                    _pending.Remove(id);
            }
        }
    }

    public bool TryComplete(string correlationId, object response)
    {
        TaskCompletionSource<object>? tcs;
        lock (_sync)
        {
            if (!_pending.Remove(correlationId, out tcs)) return false;
        }
        return tcs.TrySetResult(response);
    }
}
